135	interface RebakePanelProps {
136	  /** The fingerprint the server just rendered, whichever render that was. */
137	  currentId: string;
138	  /** The instrument's reference bar — code drawer plus docs/source links. */
139	  references?: React.ReactNode;
140	  /**
141	   * The server-rendered stamp, threaded through as a prop so this client
142	   * component can wrap it in the pending and landing treatments — the
143	   * server-component-as-prop composition exhibit one teaches.
144	   */
145	  stamp: React.ReactNode;
146	}
147	
148	/**
149	 * Demo 02's instrument, in the house zones: display (the stamp, which dims
150	 * while a round trip is out and flashes once when a new fingerprint lands),
151	 * narration (provenance and caption, one block), and the deck. The slow-motion
152	 * switch doesn't add a second button — it splits the one button into the two
153	 * events it was always made of.
154	 */
155	export function RebakePanel({
156	  currentId,
157	  references,
158	  stamp,
159	}: RebakePanelProps) {
160	  const router = useRouter();
161	  const [state, dispatch] = useReducer(rebakeReducer, INITIAL_REBAKE_STATE);
162	  const [isRebaking, startRebake] = useTransition();
163	  const [isFetching, startFetch] = useTransition();
164	  const [rebakeFailed, setRebakeFailed] = useState(false);
165	  // The fingerprint the page arrived with. A remount of the display wrapper
166	  // only counts as a landing once the id has moved off this — otherwise the
167	  // first paint of the page would flash as though something had changed.
168	  const initialIdRef = useRef(currentId);
169	
170	  const machinery = state.mode === "machinery";
171	  const working = isRebaking || isFetching;
172	  const rebakeLocked = !canRebake(state) || isRebaking;
173	  const fetchable = canFetch(state, currentId);
174	
175	  const handleRebake = useCallback(() => {
176	    // Guards the same lock the button's `aria-disabled` shows, since that
177	    // attribute doesn't stop clicks the way the native one does.
178	    if (rebakeLocked) {
179	      return;
180	    }
181	    setRebakeFailed(false);
182	    if (machinery) {
183	      // `currentId` closes over the fingerprint on screen at press time —
184	      // the ask stays dark until the private render has moved it.
185	      startRebake(async () => {
186	        try {
187	          const { rebakedAt } = await rebakeShell();
188	          dispatch({ at: rebakedAt, idAtExpiry: currentId, type: "expired" });
189	        } catch {
190	          // The tag may well have been expired before the response died, so
191	          // the copy promises nothing about what happened — it just says so.
192	          setRebakeFailed(true);
193	        }
194	      });
195	      return;
196	    }
197	    // The fused press: the same action, with the refill it implies chained
198	    // into the same transition. The button stays "Re-baking…" across both
199	    // halves, so the press reads as the one event it is pretending to be.
200	    startRebake(async () => {
201	      try {
202	        await rebakeShell();
203	      } catch {
204	        setRebakeFailed(true);
205	        return;
206	      }
207	      dispatch({ type: "fused" });
208	      router.refresh();
209	    });
210	  }, [currentId, machinery, rebakeLocked, router]);
211	
212	  const handleFetch = useCallback(() => {
213	    startFetch(() => {
214	      // Captured before the refresh lands, while the private render is still
215	      // the thing on screen. Both updates sit in the same transition, so the
216	      // panel keeps showing the expired state until the new bake arrives.
217	      dispatch({ privateId: currentId, type: "refetched" });
218	      router.refresh();
219	    });
220	  }, [currentId, router]);
221	
222	  const handleToggle = useCallback(() => {
223	    // Any open gap owes a refresh on the way out — landed or not, so this
224	    // checks the phase directly rather than the ask-button's stricter gate.
225	    const leavesGapOpen = state.phase === "expired";
226	    // The flip itself stays OUT of the transition: it is client-owned state,
227	    // and inside one it would not paint until router.refresh() resolved —
228	    // the switch sat frozen for the whole round trip. Only the server sync
229	    // is transitional; while it flies, `isFetching` swaps in the settling
230	    // readout so the flipped view doesn't claim a shared entry the stamp
231	    // isn't showing yet.
232	    dispatch({ type: "toggled" });
233	    if (leavesGapOpen) {
234	      // Leaving the machinery view with an expiry unanswered: settle it on
235	      // the way out — quietly finishing the round trip is exactly what real
236	      // apps do — so the simple view never rests showing a render the cache
237	      // refused to keep.
238	      startFetch(() => {
239	        router.refresh();
240	      });
241	    }
242	  }, [router, state]);
243	
244	  // A fetch transition still flying after the mode flipped to simple is the
245	  // settling window: the owed refresh is out, and the stamp is still the
246	  // private render until it lands.
247	  const settling = isFetching && !machinery;
248	  // During a fused press the reducer commits `fused` at the await boundary,
249	  // before the refresh lands — so the readout is held at the pre-press state
250	  // for the flight. The hook caption then arrives in the same paint as the
251	  // new fingerprint, instead of congratulating a bake that isn't up yet.
252	  const fusedInFlight = isRebaking && !machinery;
253	  const {
254	    caption,
255	    detail,
256	    label: statusLabel,
257	  } = settling
258	    ? SETTLING_READOUT
259	    : readout(fusedInFlight ? INITIAL_REBAKE_STATE : state, currentId);
260	  const rebakeLabels = machinery ? EXPIRE_LABELS : FUSED_LABELS;
261	  const rebakeLabel = isRebaking ? rebakeLabels[1] : rebakeLabels[0];
262	  const askLabel = isFetching ? ASK_LABELS[1] : ASK_LABELS[0];
263	  const captionText = rebakeFailed ? REBAKE_FAILED_CAPTION : caption;
264	
265	  const deck = (
266	    <Deck
267	      askLabel={askLabel}
268	      fetchable={fetchable}
269	      isFetching={isFetching}
270	      machinery={machinery}
271	      onFetch={handleFetch}
272	      onRebake={handleRebake}
273	      rebakeLabel={rebakeLabel}
274	      rebakeLocked={rebakeLocked}
275	      revealed={machinery && state.phase === "refetched"}
276	    />
277	  );
278	
279	  /*
280	    The view switch, in the corner every editor keeps its view controls.
281	    Disabled while either transition is in flight: a machinery press
282	    resolving after the switch flipped off would strand the simple view
283	    mid-gap, and the reducer's ignore-rule is only the fallback for that —
284	    see rebake-state.test.ts.
285	  */
286	  const viewControls = (
287	    <ViewSwitch
288	      checked={machinery}
289	      disabled={working}
290	      id="rebake-slow-motion"
291	      label="slow motion"
292	      onCheckedChange={handleToggle}
293	    />
294	  );
295	
296	  return (
297	    <LivePanel
298	      deck={deck}
299	      references={references}
300	      status={working ? "working" : "live"}
301	      viewControls={viewControls}
302	    >
303	      <div className="flex flex-col gap-5">
304	        {/* The specimen: stamp plus provenance, one table. The stamp dims
305	            and pulses while a round trip is out, and takes one amber wash
306	            when a new fingerprint lands (key remount, .ht-land). The
307	            provenance row shares the stamp's own grid so the two read as a
308	            single instrument readout. role="status" on a <dl> itself trips
309	            Biome's noInteractiveElementToNoninteractiveRole rule, so the
310	            live region wraps the row instead. */}
